describe('handle', () => {
  const baseConfig: ConnectorConfig = {
    notionApiKey: 'secret-notion-key',
    notionDatabaseId: 'db-123',
    pipedriveWonStageId: 2
  }

  const validPayload: PipedriveWebhookPayload = {
    meta: {
      action: 'change',
      entity: 'deal',
      entity_id: '8',
      timestamp: '2022-11-24T13:18:56.089Z',
      version: '2.0',
      webhook_id: '4710827',
      webhook_owner_id: '12094821',
      attempt: 1,
      host: 'pd-us.pipedrive.com'
    },
    data: {
      id: 8,
      title: 'Sample Org deal',
      value: 100,
      currency: 'EUR',
      owner_id: 12415231,
      stage_id: 2,
      status: 'won',
      won_time: '2022-11-24T13:18:55Z',
      close_time: null,
      add_time: '2022-11-24T13:18:55Z',
      update_time: null,
      creator_user_id: 12415231,
      person_id: 8,
      org_id: 1,
      pipeline_id: 1,
      probability: null,
      expected_close_date: null,
      first_won_time: null,
      lost_reason: null,
      lost_time: null,
      origin: 'ManuallyCreated',
      origin_id: null,
      label_ids: [],
      visible_to: '3',
      channel: null,
      channel_id: null,
      stage_change_time: null,
      custom_fields: {}
    },
    previous: null
  }

  it('creates a Notion page on happy path with correct request body', async () => {
    const { fetch, calls } = fakeFetch((req) =>
      req.url === 'https://api.notion.com/v1/pages' && req.method === 'POST'
        ? jsonResponse({ id: 'page-456', url: 'https://notion.so/page-456' }, 200)
        : jsonResponse({ error: 'not found' }, 404)
    )

    const result = await handle(validPayload, { ...baseConfig, fetch })

    expect(result.notionPageId).toBe('page-456')
    expect(result.notionPageUrl).toBe('https://notion.so/page-456')
    expect(calls).toHaveLength(1)

    const call = calls[0]
    expect(call.method).toBe('POST')
    expect(call.url).toBe('https://api.notion.com/v1/pages')
    expect(call.json).toEqual({
      parent: { type: 'database_id', database_id: 'db-123' },
      properties: {
        'Deal Title': { title: [{ text: { content: 'Sample Org deal' } }] },
        'Deal Value': { number: 100 },
        'Owner': { people: [{ id: '12415231' }] },
        'Close Date': { date: { start: '2022-11-24' } }
      }
    })
  })

  it('sends Authorization bearer token and Notion-Version header', async () => {
    const { fetch, calls } = fakeFetch((req) =>
      req.url === 'https://api.notion.com/v1/pages'
        ? jsonResponse({ id: 'page-789', url: 'https://notion.so/page-789' }, 200)
        : jsonResponse({ error: 'not found' }, 404)
    )

    await handle(validPayload, { ...baseConfig, fetch })

    const headers = calls[0].headers
    expect(headers.get('authorization')).toBe('Bearer secret-notion-key')
    expect(headers.get('notion-version')).toBe('2022-06-28')
    expect(headers.get('content-type')).toBe('application/json')
  })

  it('maps all fields correctly per fieldMapping', async () => {
    const { fetch, calls } = fakeFetch((req) =>
      req.url === 'https://api.notion.com/v1/pages'
        ? jsonResponse({ id: 'page-999', url: 'https://notion.so/page-999' }, 200)
        : jsonResponse({ error: 'not found' }, 404)
    )

    const payloadWithCloseTime: PipedriveWebhookPayload = {
      ...validPayload,
      data: { ...validPayload.data, close_time: '2022-11-25T10:00:00Z', won_time: null }
    }

    await handle(payloadWithCloseTime, { ...baseConfig, fetch })

    const props = (calls[0].json as Record<string, unknown>).properties as Record<string, unknown>
    expect(props['Deal Title']).toEqual({ title: [{ text: { content: 'Sample Org deal' } }] })
    expect(props['Deal Value']).toEqual({ number: 100 })
    expect(props['Owner']).toEqual({ people: [{ id: '12415231' }] })
    expect(props['Close Date']).toEqual({ date: { start: '2022-11-25' } })
  })

  it('throws descriptive error when required field is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const badPayload = { ...validPayload, data: { ...validPayload.data, title: undefined as unknown } }

    await expect(handle(badPayload as unknown as PipedriveWebhookPayload, { ...baseConfig, fetch }))
      .rejects.toThrowError('Missing required field in data: title')
  })

  it('throws error with status code and endpoint on non-2xx response', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({ error: 'unauthorized' }, 401))

    await expect(handle(validPayload, { ...baseConfig, fetch }))
      .rejects.toThrowError('Notion API error 401 on POST https://api.notion.com/v1/pages:')
  })

  it('throws error when deal is not in Won stage', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const notWonPayload = { ...validPayload, data: { ...validPayload.data, stage_id: 1, status: 'open' } }

    await expect(handle(notWonPayload, { ...baseConfig, fetch }))
      .rejects.toThrowError('Deal 8 is not in Won stage (stage_id: 1, status: open)')
  })

  it('uses close_time when won_time is null', async () => {
    const { fetch, calls } = fakeFetch((req) =>
      req.url === 'https://api.notion.com/v1/pages'
        ? jsonResponse({ id: 'page-111', url: 'https://notion.so/page-111' }, 200)
        : jsonResponse({ error: 'not found' }, 404)
    )

    const payload = {
      ...validPayload,
      data: { ...validPayload.data, won_time: null, close_time: '2022-11-26T15:30:00Z' }
    }

    await handle(payload, { ...baseConfig, fetch })

    const props = (calls[0].json as Record<string, unknown>).properties as Record<string, unknown>
    expect(props['Close Date']).toEqual({ date: { start: '2022-11-26' } })
  })

  it('falls back to add_time when both won_time and close_time are null', async () => {
    const { fetch, calls } = fakeFetch((req) =>
      req.url === 'https://api.notion.com/v1/pages'
        ? jsonResponse({ id: 'page-222', url: 'https://notion.so/page-222' }, 200)
        : jsonResponse({ error: 'not found' }, 404)
    )

    const payload = {
      ...validPayload,
      data: { ...validPayload.data, won_time: null, close_time: null, add_time: '2022-11-27T09:00:00Z' }
    }

    await handle(payload, { ...baseConfig, fetch })

    const props = (calls[0].json as Record<string, unknown>).properties as Record<string, unknown>
    expect(props['Close Date']).toEqual({ date: { start: '2022-11-27' } })
  })
})

